function rrStationHours(name){
 const m=[...new Set(TRAINS.flatMap(t=>t.route.filter(r=>r[0]===name).map(r=>timeOrdinal(r[1])%1440)))].sort((a,b)=>a-b);
 if(!m.length)return null;let gap=-1,at=0;
 for(let i=0;i<m.length;i++){const g=((m[(i+1)%m.length]-m[i])+1440)%1440||1440;if(g>gap){gap=g;at=i}}
 if(gap<180)return {allDay:true};
 const hm=x=>{x=((x%1440)+1440)%1440;return String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0')};
 return {open:hm(m[(at+1)%m.length]-30),close:hm(m[at]+15)}}
// a daily time (first / last train, opening hours), without a day mark
function rrDailyTime(x){return `<span class="time-value"><span class="time-primary">${rrMinutesToInput(timeOrdinal(x))}</span></span>`}
// first and last of a set of daily times: the first after the longest quiet spell, the last before it
function rrFirstLast(times){const m=[...new Set(times.map(x=>timeOrdinal(x)%1440))].sort((a,b)=>a-b);let gap=-1,at=0;
 for(let i=0;i<m.length;i++){const g=((m[(i+1)%m.length]-m[i])+1440)%1440||1440;if(g>gap){gap=g;at=i}}
 const hm=x=>String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0');return [hm(m[(at+1)%m.length]),hm(m[at])]}
// opening hours as one line under the station's name, with a clock (user 2026-11-22: "think of a better way to show this")
function rrStationHoursLine(name){const h=rrStationHours(name);if(!h)return '';
 return `<div class="station-hours"><svg class="rr-action-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-ui-clock"></use></svg><span>${h.allDay?'Open 24 hours':`Open ${rrDailyTime(h.open)} – ${rrDailyTime(h.close)}`}</span></div>`}
function rrServicesCard(svc,station){
 const groups=RR_SERVICE_GROUPS.map(([g,types])=>[g,svc.filter(x=>types.includes(x.type))]);
 for(const x of svc)if(!RR_SERVICE_GROUPS.some(([,types])=>types.includes(x.type))){let g=groups.find(([k])=>k===x.type);if(!g)groups.push(g=[x.type,[]]);g[1].push(x)}   // a kind not listed yet still shows, under its own name
 return `<section class="rr-card"><h3 class="rr-card-title">Services</h3>${groups.filter(([,l])=>l.length).map(([g,l])=>`<h4 class="rr-card-sub station-svc-group">${g}</h4><div class="station-services">${l.map(rrServiceRow).join('')}</div>`).join('')}${S.get(station)?.conn?.length?`<h4 class="rr-card-sub station-svc-group">Connections</h4><div class="station-services">${S.get(station).conn.map(c=>rrConnRow(c,station)).join('')}</div>`:''}</section>`}
/* Route details: one Regio or Local line on one network. Next departures from the station you came from (3 each way),
   and a line diagram of the whole route with one lane per stopping pattern (RS stops everywhere, RX only at its stops). */
function fillRouteInfo(type,net,line,from=currentStation){rrLocalSystem=null;rrFocusSystem=null;
 // Lanes: RX and RS for a Regio line; every branch of a Local letter line (A1, A2…); otherwise the line itself.
 // (Havenbolme S-lines are separate lines, not branches.)
 const branchOf=l=>String(l).replace(/\d+/g,''),branched=type==='Local'&&net!=='Havenbolme';
 const trains=TRAINS.filter(t=>t.type===type&&t.network===net&&(branched?branchOf(t.line)===branchOf(line):t.line===line));if(!trains.length)return;
 if(trains.some(t=>t.ring))return rrRingRoute(type,net,line,from);
 const keyOf=t=>type==='Regio'?t.pattern:t.line;
 let lanes=type==='Regio'?['AX','RX','RS'].filter(p=>trains.some(t=>t.pattern===p)):[...new Set(trains.map(t=>t.line))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
 const dir1=k=>trains.filter(t=>keyOf(t)===k&&t.dir===1).sort((a,b)=>b.route.length-a.route.length)[0];
 lanes=lanes.filter(k=>dir1(k));
 const runs=Object.fromEntries(lanes.map(k=>[k,dir1(k).route.map(r=>r[0])])),stopsOf=Object.fromEntries(lanes.map(k=>[k,new Set(runs[k])]));
 // one station list for all lanes: the longest lane, then each other lane's own stations where they belong;
 // a branch stored the other way round is turned to face the same way first
 const all=[...runs[[...lanes].sort((a,b)=>runs[b].length-runs[a].length)[0]]];
 for(const k of lanes){const ix=runs[k].map(n=>all.indexOf(n)).filter(i=>i>=0);if(ix.length>1&&ix[0]>ix[ix.length-1])runs[k]=[...runs[k]].reverse()}
 for(const k of lanes){let cur=-1,pending=[];
  for(const n of runs[k]){const at=all.indexOf(n);
   if(at<0){pending.push(n);continue}
   if(pending.length){all.splice(cur<0?at:cur+1,0,...pending);pending=[]}
   cur=all.indexOf(n)}
  if(pending.length)all.splice(cur+1,0,...pending)}
 const sample=Object.fromEntries(lanes.map(k=>[k,trains.find(t=>keyOf(t)===k)]));
 const span=Object.fromEntries(lanes.map(k=>{const ix=runs[k].map(n=>all.indexOf(n));return [k,[Math.min(...ix),Math.max(...ix)]]}));
 rrDetailsHeading('Route details','rr-ui-more');$('focusRoute').hidden=false;
 let deps='';
 if(all.includes(from)){
  const up=upcoming(from).filter(t=>trains.includes(t)||(t.type===type&&t.network===net&&lanes.includes(keyOf(t))&&(type!=='Regio'||t.line===line))),groups=new Map();
  for(const t of up){if(!groups.has(t.dest))groups.set(t.dest,[]);if(groups.get(t.dest).length<3)groups.get(t.dest).push(t)}
  deps=`<section class="rr-card"><h3 class="rr-card-title">Next departures from ${from}</h3>${[...groups].map(([dest,list])=>`<div class="route-dir"><div class="rr-card-sub">Towards ${rrStnText(dest)}</div>${list.map(t=>`<button type="button" class="route-dep" data-train="${t.id}"><span class="route-dep-time">${stopTimeMarkup(t,t.hereIndex)}</span>${rrBadge(t)}<span class="route-dep-main"><span class="route-dep-dest">${t.dest}</span><span class="route-dep-status">${statusTag(rrBoardStatus(t,false))}</span></span><span class="route-dep-plat" title="Platform">${rrBoardPlatform(t,from)}</span></button>`).join('')}</div>`).join('')||'<div class="rr-card-sub">No more departures today.</div>'}</section>`;
 }
 const many=lanes.length>1;
 const rows=all.map((n,i)=>`<div class="route-row${n===from?' is-here':''}${many&&lanes.every(k=>stopsOf[k].has(n))?' all-stop':''}">${lanes.map(k=>{const [a,b]=span[k];return `<span class="route-lane lane-${k}${stopsOf[k].has(n)?' stops':''}${i<a||i>b?' off':''}${i===a?' first':''}${i===b?' last':''}"></span>`}).join('')}<button type="button" class="route-stn" data-station="${n}">${rrWrapStationName(n)}</button></div>`).join('');
 // RX and RS (user's choice 2026-11-20): one line, as on most line maps - where RX (and RS) stop: a big ring and the name in bold;
 // where only RS stops: a small dot and a plain name; the key names the stopping patterns by badge, without the route number. Same marks as the map (ring = RX stop, small dot = RS only).
 const pattern=type==='Regio'&&many&&stopsOf.RX&&stopsOf.RS;
 const pRows=pattern?all.map((n,i)=>{const major=stopsOf.RX.has(n);return `<div class="rp-row${n===from?' is-here':''}${i===0?' is-first':''}${i===all.length-1?' is-last':''}${major?' rp-major':''}"><span class="rp-line" aria-hidden="true"></span><button type="button" class="route-stn" data-station="${n}">${rrWrapStationName(n)}</button></div>`}).join(''):'';
 const pKey=pattern?`<div class="route-legend rp-key"><span><span class="rp-key-mark rp-key-major" aria-hidden="true"></span>${rrBadge({...sample.RX,label:'RX'})}${rrBadge({...sample.RS,label:'RS'})}</span><span><span class="rp-key-mark" aria-hidden="true"></span>${rrBadge({...sample.RS,label:'RS'})}<span>only</span></span></div>`:'';
 // termini: the two ends of the line, each listing its terminus (one per branch when the line branches there)
 const inner=new Set(lanes.flatMap(k=>runs[k].slice(1,-1)));
 const ends=[0,1].map(side=>{const e=[...new Set(lanes.map(k=>side?runs[k][runs[k].length-1]:runs[k][0]))],outer=e.filter(n=>!inner.has(n));return outer.length?outer:e});
 const legend=type==='Regio'&&many?`<div class="route-legend">${lanes.map(k=>`<span>${rrBadge(sample[k])} ${k==='RS'?'all stations':'main stations only'}</span>`).join('')}<span class="route-legend-map"><span class="map-key-rx" aria-hidden="true"></span>RX stop<span class="map-key-rs" aria-hidden="true"></span>RS only</span></div>`
  :'';
 // Local line: first and last trains at the station you are at (user 2026-11-22: "when i selected a station + in route details, i want
 // to know if i am at that station, what is first last train time towards what direction"; sorted by pattern). One row per direction
 // (destination) and stopping pattern (all stations, then Fast); daily times without day marks. Not at a station of the line: from
 // each way's first station.
 const firstLast=type!=='Local'?'':(()=>{const at=trains.some(t=>t.route.slice(0,-1).some(r=>r[0]===from))?from:null,groups=new Map();
  for(const t of trains){const r=at?t.route.find((r,i)=>r[0]===at&&i<t.route.length-1):t.route[0];if(!r)continue;const k=[t.dir,t.dest,t.fast?1:0].join('|');if(!groups.has(k))groups.set(k,{t,st:r[0],deps:[]});groups.get(k).deps.push(r[1])}
  if(!groups.size)return '';
  const rows=[...groups.values()].sort((a,b)=>a.t.dir-b.t.dir||a.t.dest.localeCompare(b.t.dest)||(a.t.fast?1:0)-(b.t.fast?1:0)).map(g=>{const [f,l]=rrFirstLast(g.deps);
   return `<tr class="route-firstlast"><td>${g.t.dest}${g.t.fast?'<span class="rr-fast-tag">Fast</span>':''}${at?'':`<span class="fl-from">from ${g.st}</span>`}</td><td>${rrDailyTime(f)}</td><td>${rrDailyTime(l)}</td></tr>`}).join('');
  return `<section class="rr-card"><h3 class="rr-card-title">First and last trains</h3>${at?`<p class="fl-at">From ${at}</p>`:''}<table class="rr-firstlast"><thead><tr><th>Towards</th><th data-rr-fr="Premier">First</th><th data-rr-fr="Dernier">Last</th></tr></thead><tbody>${rows}</tbody></table></section>`})();
 detail.innerHTML=`<div class="train-hero route-hero" data-route="${type}|${net}|${line}"><div class="route-badges">${(type==='Regio'?lanes:[lanes[0]]).map(k=>rrBadge(sample[k])).join('')}</div><div class="route-op">${rrSystemLink(type,net)}</div>${rrLineEnds(ends[0],ends[1],rrTrainCss(sample[lanes[0]]),true)}</div>${deps}${firstLast}<section class="rr-card" style="--route:${rrTrainCss(sample[lanes[0]])}"><h3 class="rr-card-title">Route</h3>${pattern?`${pKey}<div class="route-pattern" style="--route:${rrTrainCss(sample[lanes[0]])}">${pRows}</div>`:`${legend}<div class="route-diagram" style="--route:${rrTrainCss(sample[lanes[0]])};--lanes:${lanes.length}">${rows}</div>`}</section>`;
 detail.querySelectorAll('.route-dep').forEach(b=>b.addEventListener('click',()=>{const row=upcoming(from).find(t=>t.id===b.dataset.train);if(row){setCurrentStation(from);chooseTrain(row)}}));
 detail.querySelectorAll('.route-stn').forEach(b=>b.addEventListener('click',()=>{setCurrentStation(b.dataset.station);fillStationInfo(b.dataset.station)}));
 // the map shows the whole line: every branch, in the line colour; RS-only stops get a small dot, RX stops a ring
 const full=lanes.map(dir1).sort((a,b)=>b.route.length-a.route.length)[0];
 selectedJourney=null;selectedLegPaths=[];selectedTrain=null;manualTrace=false;routeColor=rrMapColor(full);
 if(branched&&many){selectedLegPaths=lanes.map(k=>({path:getTrainPath(dir1(k)),color:routeColor}));selectedPath=selectedLegPaths.flatMap(p=>p.path)}
 else selectedPath=getTrainPath(full);
 selectedNames=all;selectedRouteLine=full;
 rrRouteMinor=type==='Regio'&&stopsOf.RX&&stopsOf.RS?new Set(runs.RS.filter(n=>!stopsOf.RX.has(n))):new Set();
 drawBoard();drawRoute();drawMap();
 detail.scrollTop=0;app.classList.add('detail-open');requestAnimationFrame(()=>{resize();focusRoute()});rrSyncHash();
}
/* A ring line's route details (user 2026-11-20): the trains go all the way round, so the page shows the ring as a loop - the
   stations in clockwise order (from the station you came from), a return track closing the loop, clockwise down the list and
   anticlockwise up it - and the next departures each way round. */
function rrRingRoute(type,net,line,from=currentStation){
 const trains=TRAINS.filter(t=>t.ring&&t.network===net);if(!trains.length)return;
 const cw=trains.filter(t=>t.ring==='cw').sort((a,b)=>b.route.length-a.route.length)[0]||trains[0];
 const loop=cw.route.map(r=>r[0]);if(loop.length>1&&loop[0]===loop.at(-1))loop.pop();
 const k=loop.indexOf(from),order=k>0?loop.slice(k).concat(loop.slice(0,k)):loop;
 const ccw=trains.find(t=>t.ring==='ccw'),badges=net==='Havenbolme'&&ccw?rrBadge(cw)+rrBadge(ccw):rrBadge(cw);
 rrDetailsHeading('Route details','rr-ui-more');$('focusRoute').hidden=false;
 let deps='';
 if(order.includes(from)){const up=upcoming(from).filter(t=>t.ring&&t.network===net),g=new Map();
  for(const t of up){if(!g.has(t.ring))g.set(t.ring,[]);if(g.get(t.ring).length<3)g.get(t.ring).push(t)}
  deps=`<section class="rr-card"><h3 class="rr-card-title">Next departures from ${from}</h3>${['cw','ccw'].filter(w=>g.has(w)).map(w=>`<div class="route-dir"><div class="rr-card-sub ring-dir">${rrRingIcon({ring:w})}<span>${rrRingName(w)}</span></div>${g.get(w).map(t=>`<button type="button" class="route-dep" data-train="${t.id}"><span class="route-dep-time">${stopTimeMarkup(t,t.hereIndex)}</span>${rrBadge(t)}<span class="route-dep-main"><span class="route-dep-dest">via ${(rrVia(t,false).map(rrStnText).join(' · '))||rrStnText(t.dest)}</span><span class="route-dep-status">${statusTag(rrBoardStatus(t,false))}</span></span><span class="route-dep-plat" title="Platform">${rrBoardPlatform(t,from)}</span></button>`).join('')}</div>`).join('')||'<div class="rr-card-sub">No more departures today.</div>'}</section>`}
 // the ring as a long oval (user 2026-11-20): stations evenly down both sides - clockwise down the right side from the station
 // you came from, then up the left
 const major=n=>LABELS.includes(n)||/[MR]/.test(S.get(n)?.sys||'');
 const h=Math.ceil(order.length/2),right=order.slice(0,h),left=order.slice(h).reverse();
 const cell=(n,side)=>n?`<button type="button" class="route-stn ro-${side}${major(n)?' ro-major':''}${n===from?' is-here':''}" data-station="${n}">${rrWrapStationName(n)}</button>`:'<span></span>';
 const mark=(n,side)=>n?`<span class="ro-mark ro-mark-${side}${major(n)?' ro-major':''}${n===from?' is-here':''}" aria-hidden="true"></span>`:'';
 const rows=right.map((n,i)=>`<div class="ro-row">${cell(left[i],'l')}<span class="ro-mid">${mark(left[i],'l')}${mark(n,'r')}</span>${cell(n,'r')}</div>`).join('');
 detail.innerHTML=`<div class="train-hero route-hero" data-route="${type}|${net}|${line}"><div class="route-badges">${badges}</div><div class="route-op">${rrSystemLink(type,net)}</div><div class="ring-facts">Ring line</div></div>${deps}<section class="rr-card" style="--route:${rrTrainCss(cw)}"><h3 class="rr-card-title">Route</h3><div class="ring-oval" style="--route:${rrTrainCss(cw)}" role="group" aria-label="Ring line: clockwise down the right side, anticlockwise up it">${rows}</div></section>`;
 detail.querySelectorAll('.route-dep').forEach(b=>b.addEventListener('click',()=>{const row=upcoming(from).find(t=>t.id===b.dataset.train);if(row){setCurrentStation(from);chooseTrain(row)}}));
 detail.querySelectorAll('.route-stn').forEach(b=>b.addEventListener('click',()=>{setCurrentStation(b.dataset.station);fillStationInfo(b.dataset.station)}));
 selectedJourney=null;selectedLegPaths=[];selectedTrain=null;manualTrace=false;routeColor=rrMapColor(cw);
 selectedPath=getTrainPath(cw);selectedNames=order;selectedRouteLine=cw;rrRouteMinor=new Set();
 drawBoard();drawRoute();drawMap();
 detail.scrollTop=0;app.classList.add('detail-open');requestAnimationFrame(()=>{resize();focusRoute()});rrSyncHash();
}
function rrBackToJourneyMarkup(){return `<button type="button" class="back-to-train" id="backToJourney"><span aria-hidden="true"><svg class="rr-arrow-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-picto-arrow-left"></use></svg></span><span>Back to journey</span></button>`}
// back to a journey as it was left: chosen, its legs' stops open or shut, its scroll places
function rrReturnToJourney(ret){
 viewMode='journeys';updateBoardTabs();chooseJourney(ret.journey);
 detail.querySelectorAll('.jt-calls-toggle').forEach((b,i)=>{if(ret.calls?.[i])b.click()});
 if(ret.scroll!=null)detail.scrollTop=ret.scroll;if(ret.boardScroll!=null)board.scrollTop=ret.boardScroll;
 rrSyncHash()}
function fillStationInfo(name=currentStation, returnTrain=null, returnJourney=null){rrLocalSystem=null;rrFocusSystem=null;
 rrDetailsHeading('Station information','rr-ui-info');$('focusRoute').hidden=true;
 const facilities=stationFacilities(name);
 const additional=facilities.filter(f=>!STATION_CORE.includes(f));
 const tierHours=STATION_HOURS[rrStationTier(name)],hours=rrCityCheckIn(name)?{...tierHours,'City check-in':tierHours['RR Services']}:tierHours,help=STATION_HELP.filter(f=>hours[f]),fault=rrStationFault(name);rrFacStation=name;
 const backButton=returnTrain?`<button type="button" class="back-to-train" id="backToTrain" aria-label="Back to train ${rrTrainLabel(returnTrain.train)}"><span aria-hidden="true"><svg class="rr-arrow-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-picto-arrow-left"></use></svg></span><span>Back to</span>${rrBadge(returnTrain.train)}</button>`:returnJourney?rrBackToJourneyMarkup():'';
 const svc=rrStationServices(name),plats=new Set(TRAINS.map(t=>t.platforms?.[name]).filter(Boolean));
 detail.innerHTML=`${backButton}<div class="train-hero station-hero" data-station="${name}"><div class="station-name-band">${name}</div>${rrStationHoursLine(name)}<div class="station-actions">${[['departures','Departures'],['arrivals','Arrivals'],['from','Journey from here'],['to','Journey to here']].map(([k,l])=>`<button type="button" class="station-action" data-action="${k}"><span>${l}</span><svg class="rr-arrow-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-picto-arrow-right"></use></svg></button>`).join('')}</div></div>
 ${rrServicesCard(svc,name)}
 <section class="rr-card"><h3 class="rr-card-title">Facilities</h3>${help.length?`<h4 class="rr-card-sub">Help and services</h4><div class="station-picto-grid">${help.map(f=>rrFacilityTile(f,hours[f])).join('')}</div>`:''}<h4 class="rr-card-sub" data-rr-fr="Standard">Standard</h4><div class="station-picto-grid">${STATION_CORE.map(f=>rrFacilityTile(f,null,fault?.facility===f?fault:null)).join('')}</div>
 ${additional.length?`<h4 class="rr-card-sub" data-rr-fr="Supplémentaires">Additional</h4><div class="station-picto-grid">${additional.map(f=>rrFacilityTile(f,hours[f],fault?.facility===f?fault:null)).join('')}</div>`:''}</section>`;
 rrWireFacilityHours(detail,f=>hours[f],f=>fault?.facility===f?fault:null);
 detail.querySelectorAll('.route-link').forEach(b=>b.addEventListener('click',()=>fillRouteInfo(b.dataset.routeType,b.dataset.routeNet,b.dataset.routeLine,name)));
 detail.querySelectorAll('.station-action').forEach(b=>b.addEventListener('click',()=>{
  const k=b.dataset.action;
  if(k==='departures'||k==='arrivals'){viewMode=k;setCurrentStation(name);return}
  rrSelectValue($(k),name);pickerViews.get(k)?.sync();setViewMode('journeys');
 }));
 if(returnTrain){
  $('backToTrain').addEventListener('click',()=>{
   viewMode=returnTrain.boardMode==='arrivals'?'arrivals':'departures';
   setCurrentStation(returnTrain.station);
   const stationTrains=viewMode==='arrivals'?arriving(returnTrain.station):upcoming(returnTrain.station);
   const restored=stationTrains.find(candidate=>candidate.id===returnTrain.train.id)||returnTrain.train;
   chooseTrain(restored,true,returnTrain.journeyReturn);   // a train opened from a journey keeps its Back to journey
  });
 }
 if(returnJourney){$('backToJourney').addEventListener('click',()=>rrReturnToJourney({journey:returnJourney}))}
 detail.scrollTop=0;
 app.classList.add('detail-open');
 requestAnimationFrame(resize);
 rrSyncHash();
}

$('stationInfoLeft').addEventListener('click',()=>fillStationInfo(currentStation));

