 rrFocusSystem={type,net,names:stations,lines:regio?[...new Map(trains.filter(t=>t.dir===1).map(t=>[t.line+'|'+t.pattern,t])).values()].map(t=>[getTrainPath(t),rrMapColor(t)]):[]};
