  // Board at the last stop in the From place (a train through several of a city's stations), alight at the first stop in To.
  let i=t.route.findIndex(p=>F.has(p[0]));while(i>=0&&i+1<t.route.length&&F.has(t.route[i+1][0]))i++;
  const j=t.route.findIndex(p=>T.has(p[0])),jd=i>=0?t.route.findIndex((p,k)=>k>i&&T.has(p[0])):-1;
